}

Method.Source:
/// <summary>
///    Finds or creates a <c>TmpInventTransMark</c> record with values from an <c>InventTrans</c> record.
/// </summary>
/// <param name="_inventTrans">
///    The <c>InventTrans</c> record.
/// </param>
/// <param name="_inventTransOrigin">
///    The <c>inventTransOrigin</c> record to be used to initialize the fields.
/// </param>
protected TmpInventTransMark findOrCreateTmpInventTransMark(InventTrans _inventTrans, InventTransOrigin _inventTransOrigin)
{
    TmpInventTransMark avaTmpInventTransMark = next findOrCreateTmpInventTransMark(_inventTrans, _inventTransOrigin);
    InventTransferTable avaInventTransferTable  = InventTransferTable::find(avaTmpInventTransMark.TransRefId);

    if(inventTransOrigin.ReferenceId == avaInventTransferTable.AVAPOReference)
    {
        avaTmpInventTransMark.AVAInventTransOriginId = inventTransOrigin.RecId;
    }

    return avaTmpInventTransMark;
}
